#!/usr/bin/env bash
#
# Puts scripts/coverage_diff_report.py's rendered report in the pull request
# conversation, as ONE comment edited in place on every push rather than a new
# one each time -- the same reasoning pr-warnings-comment.sh already carries
# for the advisory findings, applied to a second surface.
#
# Editing in place is the point: a number that changes on every push would
# otherwise leave a column of near-identical comments, and an edit does not
# re-notify subscribers. The trade is that the comment keeps its original
# position in the thread rather than floating to the bottom, which is why it
# names the commit it measured.
#
# Unlike pr-warnings-comment.sh, this body needs no escape_for_markdown: every
# byte in it was generated by coverage_diff_report.py from coverage.py's own
# data and this repository's own file paths, never from a pull request
# author's text, so there is nothing here to defuse.
set -euo pipefail

readonly MARKER="<!-- ci:coverage-report -->"

# GitHub rejects a comment body over 65536 characters. Left short of that, the
# same way pr-warnings-comment.sh reserves room for its own fixed parts.
readonly BODY_MAX=60000

body_file="$(mktemp)"
readonly body_file
trap 'rm -f "${body_file}"' EXIT

report="$(cat "${REPORT_FILE}")"

# Cut on a line boundary, then close whatever <details> was left open by the
# cut, so a truncated report never ships with an unclosed tag that would
# swallow the footer into a collapsed section. Mirrors coverage-report.mjs's
# own truncation, which exists because a blind byte-offset cut landed inside
# the one unbounded section (the uncovered-lines list) on close to every long
# report it was tried against.
if [ "${#report}" -gt "${BODY_MAX}" ]; then
  kept="${report:0:${BODY_MAX}}"
  kept="${kept%$'\n'*}"
  # `grep -o` exits 1 when nothing matches -- the common case for `closes`,
  # since a cut nearly always lands before the closing tag it is looking for
  # -- and under `pipefail` that failure would otherwise abort the whole
  # script here, silently, before anything is posted.
  opens="$(grep -o '<details' <<< "${kept}" | wc -l | tr -d ' ' || true)"
  closes="$(grep -o '</details>' <<< "${kept}" | wc -l | tr -d ' ' || true)"
  unclosed=$((opens - closes))
  close=""
  for _ in $(seq 1 "${unclosed}" 2> /dev/null || true); do
    close="${close}"$'\n</details>\n'
  done
  report="${kept}${close}"$'\n_Truncated -- see the full report in the job summary._'
fi

# Whether `/coverage-report` works right now, asked rather than assumed.
# workflow_dispatch and issue_comment fire only for a copy of the file on the
# DEFAULT branch, wherever the branch under test has it -- so the command
# exists exactly when coverage-on-demand.yml reaches main, and the contents
# API with no `?ref=` answers that for free by reading the default branch.
# A missing line is never wrong; an unearned one is, so any failure here
# is read as "not live" rather than surfaced as an error.
command_live=false
if gh api "repos/${REPO}/contents/.github/workflows/coverage-on-demand.yml" \
  > /dev/null 2>&1; then
  command_live=true
fi

{
  printf '%s\n\n' "${MARKER}"
  printf '%s\n' "${report}"
  printf '\n---\n\n'
  if [ -n "${HEAD_SHA:-}" ]; then
    # Bare SHA, never backticked: GitHub autolinks a bare hex token to the
    # commit and renders a backticked one as inert code.
    printf 'Measured on %s' "${HEAD_SHA}"
    if [ -n "${RUN_URL:-}" ]; then
      printf ' · [run log](%s)' "${RUN_URL}"
    fi
    printf '\n\n'
  fi
  if [ "${command_live}" = true ]; then
    # The backticks below are literal Markdown, not shell expansion.
    # shellcheck disable=SC2016
    printf '_To measure this pull request again, comment `/coverage-report` on it. '
    printf 'The command is accepted from members and collaborators of this '
    printf 'repository, and the new numbers replace this comment rather than '
    printf 'adding another one._\n'
  fi
} > "${body_file}"

# Same lookup pr-warnings-comment.sh uses: paginated and filtered server-side,
# redirected to a file rather than piped, so `gh` always finishes even when it
# finds more than one match.
gh api "repos/${REPO}/issues/${PR_NUMBER}/comments" --paginate \
  --jq ".[] | select(.user.type == \"Bot\") | select(.body | startswith(\"${MARKER}\")) | .id" \
  > "${body_file}.ids"
existing="$(head -n 1 "${body_file}.ids")"
rm -f "${body_file}.ids"

if [ -n "${existing}" ]; then
  gh api -X PATCH "repos/${REPO}/issues/comments/${existing}" -F "body=@${body_file}"
else
  gh pr comment "${PR_NUMBER}" --repo "${REPO}" --body-file "${body_file}"
fi
